import{createBrackishWater}from'./water.mjs';
const pins={"gain-q16.bin":{"sha256":"c42ee7a330773fddec1df8d10c30ea6231f12935013b30f4d6a74eb8cf3af3a3","bytes":749568},"allowed.bin":{"sha256":"7edd47f822a911273362d920cbef26ebcced422186cd743c87ba85b9bcb82824","bytes":749568},"source.bin":{"sha256":"e6dcaf6d4ac6c8a1d2a2a7e360526f9c4b3f039bc1b2d0fa8949edf96bae85ee","bytes":2998272}};
const sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
export async function loadBrackishWater({fetcher=fetch,signal}={}){const check=()=>{if(signal?.aborted)throw Error('BRACKISH_WATER_CANCELLED')};check();const read=async name=>{check();const r=await fetcher(new URL('assets/'+name,import.meta.url),{signal});if(!r.ok)throw Error('BRACKISH_WATER_HTTP');const raw=await r.arrayBuffer(),b=raw instanceof ArrayBuffer?new Uint8Array(raw.slice(0)):new Uint8Array(raw);check();if(b.length!==pins[name].bytes||await sha(b)!==pins[name].sha256)throw Error('BRACKISH_WATER_PIN');return b};const[source,allowed,gainQ16]=await Promise.all(['source.bin','allowed.bin','gain-q16.bin'].map(read));check();const layer=createBrackishWater({source,allowed,gainQ16});try{check();return layer}catch(e){layer.dispose();throw e}}
